def comps(grid):
    h,w=len(grid),len(grid[0]); seen=set(); out=[]
    for r in range(h):
      for c in range(w):
        color=grid[r][c]
        if color==0 or (r,c) in seen: continue
        stack=[(r,c)]; seen.add((r,c)); cells=[]
        while stack:
          x,y=stack.pop(); cells.append((x,y))
          for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
            if 0<=nx<h and 0<=ny<w and (nx,ny) not in seen and grid[nx][ny]==color:
              seen.add((nx,ny)); stack.append((nx,ny))
        out.append((color,cells))
    return out

def transform(grid):
    g=[row[:] for row in grid]; h,w=len(g),len(g[0]); objects=comps(g)
    while True:
      moves=[]
      for color,cells in objects:
        own=set(cells); ok=True
        for r,c in cells:
          nc=c+1
          if nc>=w or (g[r][nc]!=0 and (r,nc) not in own):
            ok=False; break
        if ok: moves.append((color,cells))
      if not moves: break
      moving={p for _,cs in moves for p in cs}
      # clear all moving objects then redraw shifted positions
      for r,c in moving: g[r][c]=0
      newobjs=[]
      for color,cells in objects:
        if (color,cells) in []: pass
      moving_ids={id(cells) for _,cells in moves}
      next_objects=[]
      for color,cells in objects:
        if id(cells) in moving_ids:
          shifted=[(r,c+1) for r,c in cells]
          for r,c in shifted: g[r][c]=color
          next_objects.append((color,shifted))
        else: next_objects.append((color,cells))
      objects=next_objects
    return g

